repo.reset("src/limits.rs")
hits = repo.search("expected rejection at 5")
status = repo.status()
listing = []
stack = ["."]
for i in range(4):
    newstack = []
    for d in stack:
        for e in repo.list(d):
            p = e if d == "." else d + "/" + e
            listing.append(p)
            if e.endswith("/"):
                newstack.append(p.rstrip("/") if False else p[:-1])
    stack = newstack
return {
  "limits_after_reset": repo.read("src/limits.rs"),
  "status": [str(s.path) + " " + s.kind for s in status],
  "hits": ["%s:%d: %s" % (h.path, h.line, h.text.strip()) for h in hits],
  "listing": listing,
}

